package org.jsoup.helper;

import org.jsoup.Connection;
import org.junit.Test;

import java.io.UnsupportedEncodingException;
import java.net.MalformedURLException;
import java.net.URL;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class UrlBuilderTest {
    @Test
    public void buildTest() {
        URL inputUrl = null;
        try {
            inputUrl = new URL("https://www.example.com/");
        } catch (MalformedURLException e) {
            e.printStackTrace();
        }
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URL builtUrl = urlBuilder.build();
        assertNotNull(builtUrl);
        assertTrue(builtUrl.toString().contains("https://www.example.com"));
    }

    @Test
    public void appendKeyValTest() throws UnsupportedEncodingException {
        URL inputUrl = null;
        try {
            inputUrl = new URL("https://www.example.com/");
        } catch (MalformedURLException e) {
            e.printStackTrace();
        }
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        urlBuilder.appendKeyVal(kv);
        assertTrue(urlBuilder.build().toString().contains("key=value"));
    }
}
```

This code tests the `build` and `appendKeyVal` methods of the `UrlBuilder` class.

The `buildTest` method tests the `build` method by creating an instance of `UrlBuilder` with a sample URL and then verifying that the returned URL is not null and contains the expected URL.

The `appendKeyValTest` method tests the `appendKeyVal` method by creating an instance of `UrlBuilder` with a sample URL, creating a sample `KeyVal` object, and then appending it to the `UrlBuilder`. The test then verifies that the resulting URL contains the expected key-value pair.



